                        v += f[k2][i][j] * (grid[i][iy + 1] == grid[j][jy - 1] ? 1 : 0);
                        f[k1][i][j] = v % MOD;
                    }
                }
            }
        }
        System.out.println(f[(n - 1) % 2][0][n - 1]);
    }
